-- D-26 Preventive Maintenance Program: FSQM-029 + FRM-508 Monthly Maintenance Check + FRM-509
-- Maintenance and Repair Record, all DRAFT.
--
-- SQF 11.2.1.1-.8 were all Non-Compliant. Numbers from the remediation workbook: FSQM-029 reserved;
-- "FRM-5xx schedule + work-order log" -> FRM-508 and FRM-509 (FRM-501, 502, 507 taken).
--
-- Owner's answers, 2026-09-21: maintenance is done in-house or by an outside technician called when
-- something breaks; nothing is recorded; no lubricants used as maintenance; walls and ceiling painted.
--
-- FRM-508 is ONE ENTRY PER MONTH whose fixed, deletable rows ARE the maintenance schedule (11.2.1.2),
-- the same shape as FRM-705's directory: what is checked is pre-filled, and each row's pop-up says how.
-- The building row points at FRM-913 (the monthly GMP inspection) so the building is not checked twice,
-- and scales/thermometers stay with FRM-705.
--
-- FRM-509 is ONE ENTRY PER JOB: before-work notification (11.2.1.4/.5), lubricant named (11.2.1.7),
-- temporary repair with a due date (11.2.1.6), release, and the failure review back into FRM-508
-- (11.2.1.3).
--
-- FSQM-029 lists the lubricants the SOPs already use and carries the Hobart's Gearep #85 as a known gap.

begin;

do $guard$
begin
  if exists (select 1 from public.sop_documents where sop_number in ('FSQM-029', 'FRM-508', 'FRM-509')) then
    raise exception 'FSQM-029, FRM-508 or FRM-509 already exists.';
  end if;
  if (select count(*) from public.sop_documents
       where sop_number in ('FRM-004', 'FRM-913', 'FRM-705', 'FSQM-012', 'FSQM-030', 'FSQM-018',
                            'SOP-501', 'SOP-502', 'SOP-503', 'SOP-504', 'SOP-901')) <> 11 then
    raise exception 'a document D-26 names does not exist.';
  end if;
end $guard$;

insert into public.sop_documents
  (sop_number, title, type, category, status, revision, sqf_reference, sqf_required, content)
values
  ('FSQM-029', 'Preventive Maintenance Program', 'fsqm', 'Food Safety Quality Manual', 'draft', 'New',
   '11.2.1.1, 11.2.1.2, 11.2.1.3, 11.2.1.4, 11.2.1.5, 11.2.1.6, 11.2.1.7, 11.2.1.8', true, $q${"purpose": "This program states how Adventure Bakery maintains and repairs its equipment and building so that the work itself does not contaminate product or packaging: who does it, the schedule it follows, how work is started and released, and how failures, temporary repairs, lubricants and paint are controlled.", "scope": "Every machine on the FRM-004 Equipment Register used in food processing, packaging or storage, the walk-in refrigerator and freezer, and the building's production, packaging and storage areas.", "definitions": "Maintenance schedule: the rows of FRM-508, one per machine or area, each saying what is checked.\nTemporary repair: a fix that keeps equipment or the building in use until a permanent fix can be made.\nFood-grade lubricant: a lubricant registered NSF H1, for incidental food contact.", "responsibility": "Management team - owns this program and the schedule, does the monthly checks and simple repairs in-house, and calls outside technicians.\nSupervisor - is told before work starts in their area and signs the release before production restarts.\nSQF Practitioner - is told before any work that could put something into product, reviews every FRM-509 entry and each month's FRM-508, and decides on product that may have been affected.\nProduction staff - do the equipment checks their SOPs give them, report faults, and do not repair or lubricate equipment.", "procedure": ["Who does maintenance", "• Routine checks and simple repairs are done in-house by the Management team.", "• Gas, refrigeration, electrical work and anything the manufacturer reserves for service is done by an outside technician, called by the Management team. Someone from the site stays with the technician.", "• Every repair, breakdown and technician visit is recorded on FRM-509 (SQF 11.2.1.1).", "The maintenance schedule", "• The schedule is FRM-508: one row per machine or area, with what is checked (SQF 11.2.1.2). It is worked through once a month and recorded as one FRM-508 entry.", "• Annual technician services are one row, marked when each is done, with the service report attached.", "• The building - walls, ceiling paint, lights, doors, pest proofing - is checked on the monthly GMP inspection (FRM-913), not twice. Its FRM-508 row says so.", "• Scale and thermometer accuracy belong to FSQM-030 and are recorded on FRM-705. FRM-508 checks only their condition.", "• A machine added to FRM-004 is added to FRM-508 before it is used. The schedule is changed in the form itself, so every later month carries the change.", "Before work starts", "• The person doing the work tells the Supervisor before starting in a processing, packaging or storage area (SQF 11.2.1.4).", "• Work is done on a non-production day or after production wherever possible (SQF 11.2.1.5). If it cannot wait, production at that machine stops and product and packaging are removed from the area or covered.", "• If the work could put something into product - wire, swarf, glass, a light fitting, overhead fixings, drilling, oil - the Supervisor and the SQF Practitioner are told first, and nothing open is left in the area (SQF 11.2.1.5).", "Release after work", "• Tools, removed parts, fasteners and debris are collected and accounted for. Anything missing is treated as possible foreign matter, and product is held.", "• Any food-contact part that was touched is cleaned and sanitised under the machine's SSOP, and the area is cleaned.", "• The Supervisor checks and signs the release on FRM-509 before production restarts on that machine or in that area.", "Failures", "• Every breakdown and failure is recorded on FRM-509, with its cause where known.", "• The SQF Practitioner reviews each entry and asks whether the failure shows a task missing or too far apart on FRM-508. If it does, FRM-508 is changed (SQF 11.2.1.3).", "• A failure that may have put something into product - oil, metal, a broken part - puts the product made since the last good check on hold under FSQM-018.", "Temporary repairs", "• A temporary repair is allowed only if it does not put product at risk: no tape, string, wire, cardboard or wood on or over food-contact surfaces, and it must be cleanable (SQF 11.2.1.6).", "• It is recorded on FRM-509 as temporary, with a date for the permanent fix, no more than 30 days away unless a part is on order.", "• Until it is fixed, it is cleaned with the machine or area, and it is looked at on every FRM-508 check and on the GMP inspection.", "• The permanent fix is a new FRM-509 entry that names the temporary one.", "Lubricants", "• Only food-grade (NSF H1) lubricant is used on food-contact equipment or on equipment above it (SQF 11.2.1.7). Technicians are told this before they start, and the product is named on FRM-509.", "• Lubricants in use:", "◦ NSF H1 oil - Kook-E-King feed-roller bushings (SOP-502)", "◦ Beldos food-approved grease - Beldos 275 seals and O-rings (SOP-503)", "◦ Food-grade grease - Groen kettle trunnion bearings, applied by the technician (SOP-504)", "◦ Gearep #85 - Hobart V-1401 planetary, the manufacturer's specification. NOT food-grade", "> THE HOBART'S PLANETARY LUBRICANT IS A KNOWN GAP. It sits directly over the open bowl. It is replaced with an NSF H1 equivalent at the mixer's next service. Until then the drip-cup check in SOP-501 and SOP-901 is the control: oil in the cup or on the shaft stops the mixer, and product mixed since the last clear check is held.", "• Lubricants are kept in their labelled containers, away from production and apart from chemicals. None is kept loose in a production area.", "Paint", "• The production walls and ceiling are painted. Paint is never applied to a product-contact surface (SQF 11.2.1.8).", "• Paint condition is checked monthly on FRM-913. Peeling or flaking paint over or near product is recorded on FRM-509 and fixed; until then the area below it is covered or not used.", "• Repainting uses a washable paint made for food-processing areas, is done on a non-production day with product and packaging out, and the paint is fully cured and the area cleaned before production."], "form_references": "FRM-508 - Monthly Maintenance Check (the maintenance schedule)\nFRM-509 - Maintenance and Repair Record\nFRM-004 - Equipment Register\nFRM-913 - GMP Inspection (building condition and paint)\nFRM-705 - Calibration Directory and Check Record", "records": "• FRM-508 entries, one per month, reviewed and signed by the SQF Practitioner\n• FRM-509 entries, one per job, with technician invoices and service reports attached\n• FRM-913 monthly GMP inspections, for the building", "governing_reference": "SQF Food Safety Code: Food Manufacturing, Edition 9 - 11.2.1.1 to 11.2.1.8 (Repairs and Maintenance).\n\nFRM-004 Equipment Register - the machines in scope.\nFSQM-012 Good Manufacturing Practices Program and FRM-913 - the monthly inspection that covers the building.\nFSQM-030 Calibration Program - device accuracy.\nThe machine SOPs and SSOPs (SOP-501 to SOP-605, SOP-901 to SOP-905) - operator checks and cleaning after work.\nFSQM-018 Non-Conforming Product and Equipment - product that may have been affected.", "revision_history": "New - 2026-09-21 - DRAFT under D-26, for the eight Non-Compliant findings against 11.2.1.\n\nWHAT THE SITE DID BEFORE (owner, 2026-09-21): maintenance and repairs were done in-house or by an outside technician called when something broke, and nothing was recorded. This program keeps that arrangement and adds a monthly check and a record of every job.\n\nLUBRICANTS: the owner said none are used as maintenance. The machine SOPs already have operators oiling the Kook-E-King bushings and greasing the Beldos seals, both with food-grade products, and the kettle's trunnions are greased by service. Those are listed in Part 7 with the Hobart's non-food-grade planetary lubricant, which is carried as a known gap.\n\nPAINT (owner, 2026-09-21): walls and ceiling are painted; nothing else."}$q$::jsonb),
  ('FRM-508', 'Monthly Maintenance Check', 'form', 'Module 11', 'draft', 'New',
   '11.2.1.2, 11.2.1.3, 11.2.1.6', true, jsonb_build_object('form_schema', $a${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": false, "requireVerification": true, "instanceTitleTemplate": "Maintenance check - {check_month}"}, "sections": [{"id": "about", "title": "1. How this record works", "fields": [{"id": "how_this_works", "type": "info", "label": "The maintenance schedule", "text": "THE ROWS BELOW ARE THE MAINTENANCE SCHEDULE (SQF 11.2.1.2). One entry is made each month, and every row gets an outcome.\n\nOpen a row to see what to check. Do the work on a non-production day where you can, and tell the Supervisor before you start (FSQM-029 Part 3).\n\nA FAULT GOES ON FRM-509. Record it there, with what was done and whether the machine was released.\n\nWhen a machine is added to FRM-004 it is added here before it is used."}]}, {"id": "checks", "title": "2. Monthly checks", "fields": [{"id": "check_month", "type": "text", "label": "Month", "width": "third", "required": true, "showInList": true, "help": "e.g. October 2026"}, {"id": "check_date", "type": "date", "label": "Date checked", "width": "third", "required": true, "defaultToday": true}, {"id": "assets", "type": "grid", "label": "Maintenance schedule and results", "rowDialog": true, "rows": {"mode": "fixed", "deletable": true, "labelHeader": "Equipment or area", "addLabel": "Add equipment", "labels": ["Planetary mixer - Hobart V-1401", "Cookie depositor - Kook-E-King", "Piston depositor - Beldos 275", "Steam-jacketed kettle - Groen TDB", "Rack oven - Revent 724", "Bench scales (both)", "Vacuum sealer", "Shrink wrapper - Smipack S560NA", "Band sealer", "Flow wrapper - S350X", "Date coders - SNEED-JET Titan and TOAUTO HP-003", "Pot and pan washer - Douglas", "Walk-in refrigerator and freezer", "Building - walls, ceiling paint, lights, doors, drains", "Annual technician services"], "defaultValues": [{"tasks": "Gear-case oil gauge; no oil in the drip cup or on the shaft; bowl lift and clamps; agitator clearance; cord and controls", "done_by": "In-house"}, {"tasks": "Cut-off wire tension and support fingers; feed-roller bushings and scrapers; belts; guards stop the machine", "done_by": "In-house"}, {"tasks": "Spare seals and Beldos grease in stock; air filter-regulator drained, pressure under 7 bar; hoses and speed regulator", "done_by": "In-house"}, {"tasks": "Relief-valve tests done twice this month; jacket water level and vacuum gauge; tilt moves freely; no leaks", "done_by": "In-house"}, {"tasks": "Door gasket; rack lift and rotation; steam output and scale; flue and vents clear", "done_by": "In-house"}, {"tasks": "Platform, cable and feet sound; scale level and not rocking", "done_by": "In-house"}, {"tasks": "Seal bar and its cover; lid gasket; vacuum pump per the manual", "done_by": "In-house"}, {"tasks": "Sealing blade and its PTFE cover; netting and conveyor; film scraps cleared from the chamber; fans", "done_by": "In-house"}, {"tasks": "PTFE sealing band and conveyor belts; heater blocks clean; cord and plug", "done_by": "In-house"}, {"tasks": "End-seal knives and mid-seal rollers; belts; colour-mark eye; guards and E-stop", "done_by": "In-house"}, {"tasks": "Print heads clean; cartridges in date; mounts secure, nothing loose over the line", "done_by": "In-house"}, {"tasks": "Wash jets and end caps; filter baskets; door gasket; final rinse reaches about 190°F", "done_by": "In-house"}, {"tasks": "Door gaskets and closers; drain and drip pan clear, no drip onto product; condenser coil not clogged", "done_by": "In-house"}, {"tasks": "Checked on the monthly GMP inspection", "done_by": "In-house"}, {"tasks": "Oven gas and burner service and steam descale; kettle jacket water and trunnions; refrigeration; mixer; washer", "done_by": "Outside technician"}], "guidance": ["• Oil gauge between the middle and the top. Drip cup clean and dry, no oil on the agitator shaft.\n• Oil in the drip cup or on the shaft: stop, tag out, record on FRM-509, and hold product mixed since the last clear check (SOP-501).\n• Bowl lift raises and locks; both bowl clamps close; agitator does not touch the bowl.\n• Planetary lubricant is Gearep #85 and is NOT food-grade - see FSQM-029 Part 7. Do not add lubricant; that is the technician's job.", "• Cut-off wire whole and tight, every support finger present.\n• Feed-roller bushings: a couple of drops of NSF H1 oil only (SOP-502), machine unplugged.\n• Open each guard with the machine running empty: it must stop.", "• Seals and O-rings are inspected at every clean (SOP-903) and replaced when worn. Here, confirm spare seals and Beldos food-approved grease are in stock.\n• Drain the air filter-regulator bowl; pressure below 7 bar; hoses not cracked; speed regulator tight.", "• The operator tests the relief valve at least twice a month (SOP-504). Confirm it was done.\n• Sight glass at or above the midpoint; gauge 20-30 inches of vacuum cold.\n• Tilt moves freely. Stiff tilt, a leak or a falling water level: stop and call service.\n• Jacket water treatment and trunnion greasing are the technician's (annual row). The grease must be food-grade (FSQM-029 Part 7).", "• Door gasket whole and sealing; rack lifts and rotates smoothly.\n• Steam is strong; scale build-up is reported for descaling.\n• Temperature and timer accuracy are checked on FRM-705 (FSQM-030), not here.\n• Gas burner service and steam-system descaling are the technician's (annual row).", "• Accuracy is checked on FRM-705 (FSQM-030). This row is the physical condition only.", "• Seal bar cover not scorched or torn; element seals evenly.\n• Lid gasket whole and seated.\n• Pump maintained as its manual describes. Record the make and model on FRM-004 at the next entry.", "• Blade and PTFE cover not worn through - a worn cover gives weak seals (SOP-601).\n• No film scraps in the shrink chamber - a fire risk and a foreign-matter source.", "• Band and belts not frayed, cracked or glazed with film; heater blocks clean.\n• Cord and plug undamaged.", "• Knives cut cleanly and are not chipped - a chipped knife is a foreign-matter risk.\n• Press the E-stop with the machine running empty: it must stop.", "• Cartridges are used within 3-4 months of opening (SOP-604).\n• Brackets and screws tight - nothing that can fall onto the line.", "• Jets clear and end caps in place; filter baskets whole.\n• Run a cycle and read the rinse gauge: about 190°F (SOP-905). Below that the ware is not sanitised - record on FRM-509.", "• Doors close and seal by themselves.\n• No water or ice dripping from the evaporator onto product or packaging.\n• Temperatures are watched by the sensors (SOP-401), not here.", "• The building is checked on FRM-913 (rows 11.1.2 building materials, 11.1.3 lighting, 11.1.5 pest proofing), not twice.\n• Mark this row 'Recorded on FRM-913'. A defect found there is recorded on FRM-509.", "• Once a year, each by a qualified technician. Mark 'Not due this month' until one is done, then attach the service report to this entry and record the visit on FRM-509.\n• Tell the technician before they start: food-grade (NSF H1) lubricant only on or over food-contact equipment, and product and packaging are out of the area."]}, "columns": [{"id": "tasks", "type": "text", "label": "What is checked", "width": 3}, {"id": "done_by", "type": "select", "label": "Done by", "options": ["In-house", "Outside technician"]}, {"id": "outcome", "type": "select", "label": "Outcome", "options": ["Done - OK", "Done - fault recorded on FRM-509", "Recorded on FRM-913", "Not due this month", "Not done - reason recorded"], "required": true}, {"id": "notes", "type": "text", "label": "Notes / FRM-509 reference", "width": 2}]}, {"id": "checked_by", "type": "signature", "label": "Checked by", "role": "filler", "required": true, "statement": "I performed the checks recorded above on the date shown."}]}, {"id": "review", "title": "3. Review", "fields": [{"id": "temporary_repairs", "type": "select", "label": "Open temporary repairs (FRM-509)", "required": true, "options": ["None open", "All still safe and within their date", "One or more overdue or no longer safe - action recorded"]}, {"id": "failures", "type": "select", "label": "Failures this month", "required": true, "options": ["None", "Recorded on FRM-509 - schedule still right", "Recorded on FRM-509 - schedule changed"]}, {"id": "review_notes", "type": "textarea", "label": "Temporary repairs still open, and any change to the schedule"}, {"id": "reviewed_by", "type": "signature", "label": "Reviewed by the SQF Practitioner", "role": "verifier", "required": true, "statement": "I have reviewed this month's maintenance, the open temporary repairs and the failures."}]}]}$a$::jsonb)),
  ('FRM-509', 'Maintenance and Repair Record', 'form', 'Module 11', 'draft', 'New',
   '11.2.1.1, 11.2.1.3, 11.2.1.4, 11.2.1.5, 11.2.1.6, 11.2.1.7', true, jsonb_build_object('form_schema', $b${"schemaVersion": 1, "settings": {"attachmentsEnabled": true, "allowMultipleDrafts": true, "requireVerification": true, "instanceTitleTemplate": "{job_date} - {equipment}"}, "sections": [{"id": "job", "title": "1. The job", "fields": [{"id": "how_this_works", "type": "info", "label": "One entry per job", "text": "Record every breakdown, repair and technician visit here, and anything found on the monthly check (FRM-508) or the GMP inspection (FRM-913) that needs fixing. Attach the technician's invoice or service report."}, {"id": "job_date", "type": "date", "label": "Date", "width": "third", "required": true, "defaultToday": true, "showInList": true}, {"id": "equipment", "type": "text", "label": "Equipment or area", "width": "third", "required": true, "showInList": true, "help": "As named on FRM-004, or the room and surface"}, {"id": "job_type", "type": "select", "label": "Type", "width": "third", "required": true, "showInList": true, "options": ["Breakdown or failure", "Repair", "Temporary repair", "Scheduled service", "Building or paint", "Other"]}, {"id": "description", "type": "textarea", "label": "What was found and what was done", "required": true}, {"id": "cause", "type": "text", "label": "Cause, if known"}, {"id": "done_by", "type": "select", "label": "Done by", "width": "half", "required": true, "options": ["In-house", "Outside technician"]}, {"id": "technician", "type": "text", "label": "Technician and company", "width": "half"}]}, {"id": "before", "title": "2. Before work started", "fields": [{"id": "supervisor_told", "type": "select", "label": "Supervisor told before work started", "width": "half", "required": true, "options": ["Yes", "No production that day - area empty"]}, {"id": "timing", "type": "select", "label": "When", "width": "half", "required": true, "options": ["Non-production day or after production", "During production - product removed or covered"]}, {"id": "threat", "type": "select", "label": "Could the work put anything into product?", "required": true, "help": "Wire, swarf, glass, a light fitting, overhead fixings, drilling, oil", "options": ["No", "Yes - SQF Practitioner told, nothing open in the area"]}, {"id": "threat_notes", "type": "text", "label": "How product was protected"}]}, {"id": "materials", "title": "3. Lubricant and parts", "fields": [{"id": "lubricant", "type": "select", "label": "Lubricant used", "width": "half", "required": true, "options": ["None", "Food-grade (NSF H1)", "Not food-grade - not on or over food-contact equipment"]}, {"id": "lubricant_name", "type": "text", "label": "Lubricant product", "width": "half"}, {"id": "parts", "type": "text", "label": "Parts replaced"}]}, {"id": "temporary", "title": "4. Temporary repair", "fields": [{"id": "is_temporary", "type": "select", "label": "Is this repair temporary?", "width": "half", "required": true, "options": ["No", "Yes"]}, {"id": "permanent_by", "type": "date", "label": "Permanent fix due by", "width": "half", "showInList": true, "help": "Within 30 days, unless a part is on order"}, {"id": "temporary_safe", "type": "text", "label": "Why it is safe meanwhile, and how it is cleaned", "help": "No tape, string, wire, cardboard or wood on or over food-contact surfaces"}, {"id": "replaces", "type": "text", "label": "Permanent fix of the temporary repair dated", "help": "Fill this in on the entry for the permanent fix"}]}, {"id": "release", "title": "5. Release", "fields": [{"id": "cleared", "type": "select", "label": "Tools, parts, fasteners and debris removed and accounted for", "required": true, "options": ["Yes", "No - item missing, product held"]}, {"id": "cleaned", "type": "select", "label": "Cleaned (and food-contact parts sanitised under the machine's SSOP)", "required": true, "options": ["Yes", "Not needed - no food-contact area touched"]}, {"id": "released_by", "type": "signature", "label": "Released for production by the Supervisor", "role": "filler", "required": true, "statement": "I have checked the equipment and area and released them for production."}]}, {"id": "review", "title": "6. Review", "fields": [{"id": "schedule_change", "type": "select", "label": "Does this show a task missing or too far apart on FRM-508?", "required": true, "options": ["No", "Yes - FRM-508 changed"]}, {"id": "product_affected", "type": "select", "label": "Could product have been affected?", "required": true, "options": ["No", "Yes - held under FSQM-018"]}, {"id": "reviewed_by", "type": "signature", "label": "Reviewed by the SQF Practitioner", "role": "verifier", "required": true, "statement": "I have reviewed this job and its effect on the maintenance schedule and on product."}]}]}$b$::jsonb));

do $verify$
declare fs jsonb; g jsonb; p jsonb;
begin
  select content->'procedure' into p from public.sop_documents where sop_number = 'FSQM-029';
  if jsonb_array_length(p) <> 40 then raise exception 'FSQM-029 procedure is % lines, expected 40.', jsonb_array_length(p); end if;
  select content->'form_schema' into fs from public.sop_documents where sop_number = 'FRM-508';
  select f into g from jsonb_array_elements(fs->'sections') s, jsonb_array_elements(s->'fields') f where f->>'id' = 'assets';
  if jsonb_array_length(g->'rows'->'labels') <> 15 or jsonb_array_length(g->'rows'->'defaultValues') <> 15
     or jsonb_array_length(g->'rows'->'guidance') <> 15 or not (g->'rows'->>'deletable')::boolean then
    raise exception 'FRM-508 schedule rows mis-built.';
  end if;
  if (select count(*) from public.sop_documents d, jsonb_array_elements(d.content->'form_schema'->'sections') s,
        jsonb_array_elements(s->'fields') f
       where d.sop_number in ('FRM-508', 'FRM-509') and f->>'type' = 'signature' and f->>'role' = 'verifier') <> 2 then
    raise exception 'FRM-508 and FRM-509 need one verifier signature each.';
  end if;
  raise notice 'D-26 drafts seeded: FSQM-029 (% lines), FRM-508 (15 rows), FRM-509.', jsonb_array_length(p);
end $verify$;

commit;
